import{_ as d,o,c,ah as t}from"./chunks/framework.DuX8SFU5.js";const N=JSON.parse('{"title":"AM_NODE_V2 — инженерные заметки","description":"","frontmatter":{},"headers":[],"relativePath":"am_node_v2/engineering.md","filePath":"am_node_v2/engineering.md"}'),a={name:"am_node_v2/engineering.md"};function i(r,e,l,n,A,s){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="am-node-v2-—-инженерные-заметки" tabindex="-1">AM_NODE_V2 — инженерные заметки <a class="header-anchor" href="#am-node-v2-—-инженерные-заметки" aria-label="Permalink to &quot;AM_NODE_V2 — инженерные заметки&quot;">​</a></h1><p>Сведения для разработки прошивки, ввода платы в эксплуатацию и производства. Характеристики, разъёмы и интерфейс CAN — в <a href="./datasheet">даташите</a>.</p><h2 id="измерение-входного-питания-в-прошивке" tabindex="-1">Измерение входного питания в прошивке <a class="header-anchor" href="#измерение-входного-питания-в-прошивке" aria-label="Permalink to &quot;Измерение входного питания в прошивке&quot;">​</a></h2><p>Для <code>am_node_f1_default</code> масштабирование задаётся в <code>src/boards/am/node_f1/board/board_monitor_config.hpp</code>. Шунт R29 = 1 mΩ и выходной резистор R30 = 22 kΩ дают номинально 22 mV/A на выходе INA169: при опорном напряжении 3,3 V и 12-битном ADC один отсчёт соответствует примерно 0,03663 A. Расчёт следует формуле <code>Vout = I × Rshunt × Rload / 1 kΩ</code> из <a href="https://www.ti.com/lit/ds/symlink/ina169.pdf" target="_blank" rel="noreferrer">даташита INA169</a>; перед использованием измерения для контроля тока коэффициент и смещение проверяют по измерительному прибору.</p><p>Общие настройки <code>BoardMonitorConfig</code> (node-core, <code>Src/drivers/board_monitor/config.hpp</code>) позволяют задать коэффициенты делителей напряжения, масштаб и смещение тока, а также допустимый диапазон ADC ревизии для плат, где наличие датчика зависит от ревизии. Для новой платы добавляют свой <code>board/board_monitor_config.hpp</code> с константой <code>BOARD_MONITOR_CONFIG</code>; менять библиотечный код при этом не требуется. Этот механизм одинаков для F1, G0, H7 и SITL: отсутствие файла сохраняет прежние коэффициенты и правила публикации, а в файле можно переопределить только нужные поля. Конфигурация масштабирования не меняет способ получения ADC: DMA, опрос нескольких ADC или симуляция остаются ответственностью существующего драйвера платы. На AM_NODE_V2 входной INA169 установлен независимо от делителя ревизии uNODE, поэтому проверка ревизии для чтения тока отключена. Калибровка F1 не переносится автоматически на FMU/H7: перед её заданием нужно проверить дополнительное масштабирование входа FMU <code>ADC3_6V6</code>, внутренней схемы которого в <code>doc.pdf</code> нет.</p><p>В прошивке F1 в <code>CircuitStatus</code> с ID <code>node_id × 10 + 1</code> публикуется ток входного питания, а с ID <code>node_id × 10</code> — напряжение 5 V и <code>current = NaN</code>: отдельного измерителя тока этой шины нет. Например, для узла 42 это ID 421 и 420 соответственно. <code>NaN</code> на шине 5 V означает отсутствие измерения, а не нулевой ток.</p><p>AM F1 включает автоматический выбор длины DMA-буфера через <code>BoardAdc::DMA_CHANNEL_COUNT = 0</code>: длина берётся из настроенной HAL последовательности (<code>hadc1.Init.NbrOfConversion</code>, один канал при отключённом сканировании); вручную дублировать число преобразований не нужно. Платы с ненулевым <code>DMA_CHANNEL_COUNT</code> сохраняют прежнюю явно заданную длину DMA; добавление файла калибровки не включает автоматический выбор. Для текущей конфигурации это пять каналов; порядок <code>RANK_*</code> в <code>adc_mapping.hpp</code> всё ещё должен соответствовать порядку преобразований в CubeMX. Неиспользуемый канал джойстика помечен отсутствующим: объявление ранга само по себе не добавляет преобразование в HAL. На H7 число измеряемых входов берётся из таблицы опрашиваемых каналов <code>board/adc.cpp</code>, поскольку она объединяет ADC1 и ADC3.</p><h2 id="поведение-параметров-каналов-load" tabindex="-1">Поведение параметров каналов LOAD <a class="header-anchor" href="#поведение-параметров-каналов-load" aria-label="Permalink to &quot;Поведение параметров каналов LOAD&quot;">​</a></h2><p>В текущей прошивке значение <code>0</code> параметров <code>bypass.b1</code>, <code>bypass.b2</code>, <code>bypass.b34</code> задаёт высокий уровень GPIO и запрашивает отключение BYPASS. Полярность общего выхода BYPASS3+4 пока принята по аналогии с BYPASS1/2 и требует аппаратной проверки. <code>INA_OCIN</code> измеряет цепь <code>Operator Control Input</code>, поэтому показания IN и OUT не обязаны совпадать при отключённом BYPASS. Наличие напряжения OUT не доказывает протекание тока через его шунт: INA228 измеряет напряжение шины и падение на шунте раздельно. Если нагрузка действительно потребляет ток через шунт OUT, его показания должны отражать этот ток; считать почти нулевое значение нормой только по настройке BYPASS нельзя. Внутренней схемы <code>Module Valve_Control</code> в <code>doc.pdf</code> нет, поэтому расположение шунта относительно обходных путей нужно проверять по схеме самого модуля.</p><h2 id="поведение-параметров-входов-sens" tabindex="-1">Поведение параметров входов SENS <a class="header-anchor" href="#поведение-параметров-входов-sens" aria-label="Permalink to &quot;Поведение параметров входов SENS&quot;">​</a></h2><p>Тип каждого входа задают параметром <code>max14906.sensN_in.type</code>: <code>0</code> — PNP, <code>1</code> — NPN, где <code>N</code> — номер разъёма от 1 до 8. По умолчанию все входы настроены как PNP. Изменение применяется во время работы без пересборки и перезагрузки: при следующем опросе модуль перенастраивает микросхему соответствующего банка из четырёх входов и считывает свежие уровни. При ошибке настройки весь этот банк сообщает недоступность измерений до успешной повторной инициализации; второй банк продолжает опрашиваться. Отдельные каналы питания датчиков (<code>max14906.sensN_out.mode</code>) при смене типа входа не переключаются. Чтобы сохранить выбранный тип после перезагрузки, выполните сохранение параметров в DroneCAN GUI. Параметр <code>max14906.sensN_in.hid</code> задаёт только ID публикации (<code>-1</code> отключает её).</p><p>При обновлении прошивки с добавлением этих параметров предварительно сохраните настройки: размер таблицы параметров изменился. После установки выполните <strong>Erase All</strong>, затем восстановите настройки по именам параметров и сохраните их.</p><p>Для NPN требуется внешняя подтяжка входа вверх и аппаратный низкий уровень на соответствующем выводе D_; инверсия публикации не заменяет эту конфигурацию подключения.</p><p>При неинициализированном драйвере <code>status = 65535</code> независимо от типа датчика; это признак недоступного измерения, а не открытого или закрытого выхода. Инверсия NPN применяется только к публикуемому состоянию: диагностические сообщения об уровнях входов показывают исходные электрические уровни.</p><h2 id="указания-для-прошивки" tabindex="-1">Указания для прошивки <a class="header-anchor" href="#указания-для-прошивки" aria-label="Permalink to &quot;Указания для прошивки&quot;">​</a></h2><ul><li><p>В прошивке должен быть выбран один целевой режим платы: <code>uNODE mode</code> на STM32F103T8 или <code>FMU mode</code> на STM32H753IIK6.</p></li><li><p><code>CAN1/CAN2</code>, Ethernet LAN8742A и USB доступны только в <code>FMU mode</code>:</p><ul><li>CAN1/CAN2 настраиваются через FDCAN-пины FMU;</li><li>Ethernet настраивать как RMII с PHY LAN8742A;</li><li>USB настраивать как FS device с D+/D− и VBUS sense.</li></ul></li><li><p>Для LAN8742A проверить адрес PHY:</p><ul><li><code>R82 installed</code> → PHY address <code>1</code>;</li><li><code>R82 DNP</code> → PHY address <code>0</code>.</li></ul></li><li><p>MAX14906 управляются через SPI. Все устройства используют общие <code>SDI</code>, <code>SDO</code>, <code>CLK</code>, <code>nCS1</code>, <code>SYNCH</code>; адрес задаётся <code>A0/A1</code>.</p></li><li><p>Для MAX14906 реализовать:</p><ul><li>чтение состояния концевиков через <code>S0/S1</code>;</li><li>управление питанием линий концевиков через <code>S0V/S1V</code>;</li><li>диагностику обрыва питания линии датчика;</li><li>обработку <code>nFAULT</code> и <code>nREADY</code>.</li></ul></li><li><p>Для <code>LOAD1</code>…<code>LOAD4</code> реализовать управление нагрузкой и BYPASS. Учесть, что BYPASS для <code>LOAD3</code> и <code>LOAD4</code> общий.</p></li><li><p>При выключенной плате BYPASS должен рассматриваться как аппаратно активный: сигнал <code>Operator Control Input</code> пробрасывается на электрогидроклапан через твердотельное реле.</p></li><li><p>INA228 доступны по I2C:</p><ul><li>8 адресов заняты измерением <code>INA_OUT</code>/<code>INA_OCIN</code> в <code>LOAD1</code>…<code>LOAD4</code>;</li><li>4 адреса заняты входами <code>C_SENS1</code>…<code>C_SENS4</code>;</li><li>шунт C_SENS — 2 Ω; для LOAD прошивка использует настраиваемое значение, по умолчанию 20 mΩ.</li></ul></li><li><p>Для <code>ADC_V_IN</code> и <code>ADC_A_IN</code> нужна калибровка по фактическому делителю, INA169 gain, шунту, ADC reference и допускам компонентов.</p></li><li><p>Добавить startup sequencing для <code>NPOWER_IN_A/B/C</code> и <code>ETH_POWER_EN</code> согласно выбранному режиму работы и финальному power tree.</p></li></ul><h2 id="проверка-при-вводе-в-эксплуатацию" tabindex="-1">Проверка при вводе в эксплуатацию <a class="header-anchor" href="#проверка-при-вводе-в-эксплуатацию" aria-label="Permalink to &quot;Проверка при вводе в эксплуатацию&quot;">​</a></h2><ul><li>Визуальная проверка: полярность XT30, USB-C, CAN, Ethernet, load и sensor connectors.</li><li>Без питания: проверить сопротивления между <code>Vin_in</code>, <code>5V</code>, <code>3V3</code> и <code>GND</code>.</li><li>Первое включение от лабораторного БП с ограничением тока: проверить 5 V и все 3.3 V rails.</li><li>Проверить масштабирование ADC входного напряжения и тока.</li><li>Для FMU mode: проверить CAN1/CAN2, RX/TX и конфигурацию терминаторов.</li><li>Для FMU mode: проверить USB enumeration через Type-C.</li><li>Для FMU mode: проверить доступ к LAN8742A по MDIO и PHY address.</li><li>Просканировать I2C и подтвердить адреса INA228 для <code>LOAD1</code>…<code>LOAD4</code> и <code>C_SENS1</code>…<code>C_SENS4</code>.</li><li>Проверить SPI-связь с MAX14906, <code>nREADY</code>, <code>nFAULT</code>, состояние концевиков и диагностику обрыва питания линий.</li><li>Проверить BYPASS для <code>LOAD1</code>…<code>LOAD4</code>, отдельно учесть общий BYPASS для <code>LOAD3</code>/<code>LOAD4</code>.</li><li>Протестировать каждый <code>LOADx</code>, <code>SENSx</code>, <code>C_SENSx</code> канал на токограниченной нагрузке до подключения финальных актуаторов.</li></ul><h2 id="данные-для-производства" tabindex="-1">Данные для производства <a class="header-anchor" href="#данные-для-производства" aria-label="Permalink to &quot;Данные для производства&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Project name</td><td><code>NODE</code></td></tr><tr><td>Hardware revision</td><td>TBD</td></tr><tr><td>PCB dimensions</td><td>82.5 mm × 98.5 mm</td></tr><tr><td>PCB layers</td><td>TBD</td></tr><tr><td>PCB thickness</td><td>TBD</td></tr><tr><td>Copper</td><td>TBD</td></tr><tr><td>Surface finish</td><td>TBD</td></tr><tr><td>Solder mask</td><td>TBD</td></tr><tr><td>Silkscreen</td><td>TBD</td></tr><tr><td>Conformal coating</td><td>TBD</td></tr><tr><td>Assembly</td><td>SMT + connectors; точная PCBA option TBD</td></tr><tr><td>Required production files</td><td>Gerbers, drill files, pick-and-place, BOM, assembly drawing, schematic PDF, test procedure</td></tr></tbody></table>',20)])])}const _=d(a,[["render",i]]);export{N as __pageData,_ as default};
